// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        CallerHelper helper = new CallerHelper();

        vm.deal(address(helper), 1 ether);

        helper.doAirDrop(address(c));

        uint256 bal = c.tokenBalance(address(helper));

        assertTrue(bal == 20);
    }
}

contract CallerHelper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    function doAirDrop(address c) external {
        ModifierEntrancy(c).airDrop();
    }
}
